For now, here's a React example with debounce:

```jsx
import { useState, useRef } from 'react';

function SearchInput() {
  const [results, setResults] = useState([]);
  const timeoutRef = useRef(null);

  const handleSearch = async (query) => {
    if (!query) {
      setResults([]);
      return;
    }
    const res = await fetch(`/api/search?q=${query}`);
    const data = await res.json();
    setResults(data);
  };

  const handleChange = (e) => {
    clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => {
      handleSearch(e.target.value);
    }, 300); // debounce delay in ms
  };

  return (
    <div>
      <input
        type="text"
        placeholder="Search..."
        onChange={handleChange}
      />
      <ul>
        {results.map((item) => (
          <li key={item.id}>{item.name}</li>
        ))}
      </ul>
    </div>
  );
}
```

**Key changes:**
- `useRef` stores the timeout ID so it can be cleared on each keystroke
- `handleChange` clears the previous timeout before setting a new one
- API call only fires 300ms after the user stops typing

